export const DOCUMENT_TEMPLATES = {
  contract:
    '<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n  <meta charset="utf-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1" />\n  <title>عقد عمل | شركة قرطبة للتوريدات</title>\n  <style>\n    :root {\n      --ink: #263238;\n      --muted: #5b6573;\n      --gold: #b08d3c;\n      --line: #cbd2d9;\n      --soft: #eef1f4;\n      --cream: #f7f3e8;\n      --paper: #fff;\n    }\n\n    * { box-sizing: border-box; }\n    html { background: #e9edf1; }\n    body {\n      margin: 0;\n      color: var(--ink);\n      background: #e9edf1;\n      font-family: Tahoma, "Arial", sans-serif;\n      line-height: 1.7;\n    }\n\n    .toolbar {\n      position: sticky;\n      top: 0;\n      z-index: 10;\n      display: flex;\n      gap: 10px;\n      align-items: center;\n      justify-content: center;\n      padding: 12px;\n      background: rgba(38, 50, 56, .96);\n    }\n    button {\n      border: 0;\n      border-radius: 5px;\n      padding: 9px 18px;\n      color: white;\n      background: var(--gold);\n      cursor: pointer;\n      font: inherit;\n    }\n    button.secondary { background: #60717d; }\n\n    .document {\n      width: 210mm;\n      min-height: 297mm;\n      margin: 20px auto;\n      padding: 18mm 17mm;\n      background: var(--paper);\n      border: 1px solid #718096;\n      box-shadow: 0 5px 24px rgba(0,0,0,.12);\n    }\n\n    .page-header {\n      display: grid;\n      grid-template-columns: 1fr 5fr 1fr;\n      align-items: center;\n      gap: 12px;\n      padding-bottom: 7px;\n      border-bottom: 2px solid var(--gold);\n      color: var(--muted);\n      font-size: 12px;\n    }\n    .page-header img { width: 42px; justify-self: start; }\n    .company-name { text-align: center; color: var(--ink); font-weight: 700; font-size: 15px; }\n\n    .cover { text-align: center; padding: 24px 0 14px; }\n    .cover img { width: 82px; }\n    .cover h1 { margin: 7px 0 0; font-size: 30px; color: var(--ink); }\n    .cover h2 { margin: 0; color: #8a6a2f; font-size: 18px; }\n    .gold-rule { width: 110px; margin: 12px auto; border-top: 2px solid var(--gold); }\n\n    .meta { text-align: center; margin: 8px 0 13px; }\n    .notice, .ack {\n      padding: 12px 14px;\n      margin: 12px 0;\n      border: 1px solid var(--gold);\n      border-radius: 4px;\n      background: var(--cream);\n    }\n\n    .bar {\n      margin: 17px 0 8px;\n      padding: 6px 10px;\n      border: 1px solid var(--gold);\n      border-right: 4px solid var(--ink);\n      border-radius: 3px;\n      background: var(--soft);\n      font-size: 16px;\n      font-weight: 700;\n    }\n    .subbar {\n      margin: 12px 0 5px;\n      padding-bottom: 3px;\n      border-bottom: 1px solid #d6c59b;\n      color: #8a6a2f;\n      font-weight: 700;\n    }\n\n    table { width: 100%; border-collapse: collapse; margin: 6px 0 12px; }\n    th, td { border: 1px solid var(--line); padding: 7px 8px; vertical-align: middle; }\n    th { background: var(--soft); font-weight: 700; }\n    .label { width: 22%; background: #fafafa; font-weight: 700; white-space: nowrap; }\n    .number { width: 7%; text-align: center; }\n\n    input, textarea, select {\n      width: 100%;\n      border: 0;\n      border-bottom: 1px dotted #555;\n      padding: 3px 2px;\n      background: transparent;\n      color: var(--ink);\n      font: inherit;\n      outline: none;\n    }\n    textarea { min-height: 44px; resize: vertical; border: 1px dotted #777; }\n    input:focus, textarea:focus, select:focus { background: #fffbea; }\n\n    .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n    .signature {\n      padding: 12px;\n      border: 1px solid var(--gold);\n      border-radius: 4px;\n      background: #fafaf8;\n    }\n    .signature h3 { margin: 0 0 12px; text-align: center; font-size: 15px; }\n    .signature p { margin: 8px 0; }\n    .stamp { height: 95px; display: grid; place-items: center; border: 1px dashed var(--gold); color: var(--muted); }\n\n    ul, ol { margin-top: 5px; padding-right: 25px; }\n    li { margin: 3px 0; }\n    .compact-list li { margin: 1px 0; }\n\n    .page-break { break-before: page; page-break-before: always; }\n    .footer-note { margin-top: 18px; padding-top: 7px; border-top: 1px solid var(--gold); color: var(--muted); font-size: 11px; display: flex; justify-content: space-between; }\n\n    @media (max-width: 850px) {\n      .document { width: 100%; margin: 0; padding: 18px; border: 0; box-shadow: none; }\n      .two-col { grid-template-columns: 1fr; }\n      .toolbar { position: static; }\n    }\n\n    @media print {\n      html, body { background: white; }\n      .toolbar { display: none; }\n      .document { width: auto; min-height: auto; margin: 0; padding: 14mm 15mm; border: 0; box-shadow: none; }\n      .page-break { break-before: page; page-break-before: always; }\n      input, textarea, select { color: #000; }\n      @page { size: A4; margin: 0; }\n    }\n  </style>\n</head>\n<body>\n  <main class="document">\n    <header class="page-header">\n      <span>عقد عمل</span>\n      <span class="company-name">شركة قرطبة للتوريدات</span>\n      <img src="{{logo}}" alt="شعار قرطبة" />\n    </header>\n\n    <section class="cover">\n      <img src="{{logo}}" alt="شعار قرطبة" />\n      <h1>عقد عمل</h1>\n      <h2>شركة قرطبة للتوريدات</h2>\n      <div class="gold-rule"></div>\n      <div class="meta">رقم العقد: {{contractNo}}　 تاريخ التحرير: {{contractDate}}</div>\n    </section>\n\n    <div class="notice">\n      هذا العقد وثيقة عمل رسمية، ويقرأ مع اللائحة الداخلية للموظفين وملحقاتها ومرفقاتها المبينة في صفحة الوثائق المرتبطة بالعقد، وتعد هذه الوثائق جزءًا مكملًا للعلاقة الوظيفية بعد تسليمها للموظف أو إتاحتها له.\n    </div>\n\n    <div class="bar">البيانات القانونية للمنشأة</div>\n    <table>\n      <tr><td class="label">الاسم التجاري</td><td>شركة قرطبة للتوريدات</td></tr>\n      <tr><td class="label">الشكل القانوني</td><td>منشأة فردية / تاجر فرد</td></tr>\n      <tr><td class="label">اسم المالك والممثل القانوني</td><td>إيمان كامل أبو زيد عطية</td></tr>\n      <tr><td class="label">رقم السجل التجاري</td><td>٢١٦١٨ — مكتب سجل تجاري مرسى مطروح</td></tr>\n      <tr><td class="label">الرقم القومي للمنشأة</td><td>٤٣٢٩٧٢٥٨٧</td></tr>\n      <tr><td class="label">الرقم الموحد للسجل التجاري</td><td>٢١٦١٨، ٧٠٠٠٠، ١٠٤٢٠</td></tr>\n      <tr><td class="label">الرقم الضريبي</td><td>٤٣٢-٩٧٢-٥٨٧ — مأمورية ضرائب مطروح</td></tr>\n      <tr><td class="label">العنوان</td><td>محافظة مطروح — شارع علم الروم</td></tr>\n      <tr><td class="label">النشاط</td><td>مواد البناء والمواد الإنشائية ومعدات السباكة والتدفئة، وتوريدات الأجهزة الكهربائية ومستلزماتها</td></tr>\n      <tr><td class="label">تاريخ بدء النشاط</td><td>٢١/٠٨/٢٠٢٢</td></tr>\n    </table>\n\n    <div class="bar">أولًا: بيانات الطرفين</div>\n    <p>تم الاتفاق في يوم {{agreementDay}} الموافق {{agreementDate}} بين:</p>\n\n    <div class="subbar">الطرف الأول — الشركة</div>\n    <table>\n      <tr><td class="label">الاسم التجاري</td><td><strong>شركة قرطبة للتوريدات</strong></td></tr>\n      <tr><td class="label">العنوان</td><td>محافظة مطروح — شارع علم الروم</td></tr>\n      <tr><td class="label">السجل التجاري</td><td>رقم ٢١٦١٨ — مكتب سجل تجاري مرسى مطروح</td></tr>\n      <tr><td class="label">الرقم القومي للمنشأة</td><td>٤٣٢٩٧٢٥٨٧</td></tr>\n      <tr><td class="label">الرقم الموحد للسجل التجاري</td><td>(٢١٦١٨، ٧٠٠٠٠، ١٠٤٢٠)</td></tr>\n      <tr><td class="label">الرقم الضريبي</td><td>٤٣٢-٩٧٢-٥٨٧</td></tr>\n      <tr><td class="label">الممثل القانوني</td><td>إيمان كامل أبو زيد عطية</td></tr>\n      <tr><td class="label">ممثل الشركة في توقيع العقد</td><td>إيمان كامل أبو زيد عطية — بصفته مالك المنشأة والممثل القانوني</td></tr>\n      <tr><td class="label">الصفة والكيان</td><td>مالك المنشأة — منشأة فردية / تاجر فرد</td></tr>\n      <tr><td class="label">مأمورية الضرائب</td><td>مأمورية ضرائب مطروح</td></tr>\n      <tr><td class="label">النشاط التجاري</td><td>بيع مواد البناء والمواد الإنشائية ومعدات السباكة والتدفئة، وتوريدات الأجهزة الكهربائية ومستلزماتها</td></tr>\n      <tr><td class="label">بدء النشاط</td><td>٢١/٠٨/٢٠٢٢</td></tr>\n    </table>\n\n    <div class="subbar">الطرف الثاني — الموظف</div>\n    <table>\n      <tr><td class="label">الاسم رباعي</td><td>{{fullName}}</td></tr>\n      <tr><td class="label">الجنسية</td><td>{{nationality}}</td></tr>\n      <tr><td class="label">رقم الهوية أو جواز السفر</td><td>{{nationalId}}</td></tr>\n      <tr><td class="label">العنوان</td><td>{{address}}</td></tr>\n      <tr><td class="label">رقم الهاتف</td><td>{{phone}}</td></tr>\n      <tr><td class="label">البريد الإلكتروني</td><td>{{email}}</td></tr>\n    </table>\n\n    <div class="bar">ثانيًا: الوظيفة ومدة العقد</div>\n    <table>\n      <tr><td class="label">المسمى الوظيفي</td><td>{{jobTitle}}</td><td class="label">القسم / الإدارة</td><td>{{department}}</td></tr>\n      <tr><td class="label">المدير المباشر</td><td>{{directManager}}</td><td class="label">مكان العمل</td><td>{{workplace}}</td></tr>\n      <tr><td class="label">تاريخ بدء العمل</td><td>{{hireDate}}</td><td class="label">نوع العقد</td><td>{{checkFixed}} محدد المدة　 {{checkIndefinite}} غير محدد المدة</td></tr>\n      <tr><td class="label">مدة العقد</td><td>{{contractDuration}}</td><td class="label">تاريخ الانتهاء</td><td>{{endDate}}</td></tr>\n      <tr><td class="label">فترة التجربة</td><td>{{probationText}}</td><td class="label">ساعات العمل اليومية</td><td>{{workHours}}</td></tr>\n    </table>\n\n    <div class="subbar">تفاصيل التعيين الإضافية</div>\n    <table>\n      <tr><td class="label">الوصف الوظيفي رقم</td><td>{{jobDescNo}}</td><td class="label">نطاق العمل</td><td>{{scope}}</td></tr>\n      <tr><td class="label">مكان أداء العمل</td><td>{{workMode}}</td><td class="label">السفر لمهام العمل</td><td>{{travel}}</td></tr>\n      <tr><td class="label">المعدات المسلمة</td><td>{{equipment}}</td><td class="label">البريد الوظيفي</td><td>{{workEmail}}</td></tr>\n      <tr><td class="label">التبعية الإدارية</td><td>{{adminDependency}}</td><td class="label">موعد المراجعة الأولى</td><td>{{firstReviewDate}}</td></tr>\n    </table>\n\n    <div class="footer-note"><span>توقيع الموظف: ................................</span><span>صفحة 1</span><span>شركة قرطبة للتوريدات</span></div>\n\n    <div class="page-break"></div>\n\n    <div class="bar">ثالثًا: الأجر والمزايا وساعات العمل</div>\n    <table>\n      <tr><td class="label">الأجر الأساسي الشهري</td><td>{{basicSalary}}</td><td class="label">طريقة الصرف</td><td>{{payMethod}}</td></tr>\n      <tr><td class="label">بدل السكن، إن وجد</td><td>{{housingAllowance}}</td><td class="label">بدل الانتقال، إن وجد</td><td>{{transportAllowance}}</td></tr>\n      <tr><td class="label">بدلات أو مزايا أخرى</td><td>{{allowances}}</td><td class="label">الحافز الشهري</td><td>{{incentive}}</td></tr>\n      <tr><td class="label">إجمالي الأجر الشهري</td><td>{{totalSalary}}</td><td class="label">تاريخ صرف الأجر</td><td>{{payDate}}</td></tr>\n      <tr><td class="label">أيام العمل</td><td>{{workDays}}</td><td class="label">موعد الدوام</td><td>{{workTime}}</td></tr>\n      <tr><td class="label">مدة الراحة</td><td colspan="3">{{restPeriod}}</td></tr>\n    </table>\n\n    <div class="bar">رابعًا: التزامات الموظف</div>\n    <ol>\n      <li>أداء العمل بأمانة وعناية ومهنية والالتزام بالدوام والتعليمات المشروعة.</li>\n      <li>المحافظة على أموال الشركة وأجهزتها ومستنداتها وعهدها وإعادتها عند الطلب أو انتهاء العمل.</li>\n      <li>المحافظة على سرية بيانات الشركة والعملاء والموردين والأسعار والعروض والمعلومات التجارية.</li>\n      <li>عدم قبول عمولات أو منافع أو هدايا تؤثر في القرارات، وعدم استخدام أنظمة الشركة لأغراض غير مشروعة.</li>\n      <li>الإبلاغ عن الأخطاء أو المخالفات أو حوادث أمن المعلومات فورًا.</li>\n    </ol>\n\n    <div class="bar">خامسًا: التزامات الشركة</div>\n    <p>تلتزم الشركة بتمكين الموظف من أداء عمله، وصرف الأجر والمزايا في مواعيدها، وتوفير بيئة عمل مهنية وآمنة قدر الإمكان، ومعاملة الموظف بعدالة واحترام، وتمكينه من الإجازات والحقوق المقررة قانونًا، والحفاظ على سرية بياناته في الحدود النظامية.</p>\n\n    <div class="bar">سادسًا: الإجازات والراحة والعمل الإضافي</div>\n    <p>يستحق الموظف الإجازات الأسبوعية والرسمية والسنوية والمرضية وغيرها وفق قانون العمل وعقد العمل وسياسات الشركة المعتمدة. ولا يعد طلب الإجازة أو العمل الإضافي معتمدًا إلا بعد موافقة الجهة المختصة بالطريقة المعتمدة.</p>\n\n    <div class="bar">سابعًا: السرية وحقوق العمل</div>\n    <p>تعد بيانات الشركة والعملاء والموردين والأسعار والعروض والملفات التي يطلع عليها الموظف بحكم عمله معلومات سرية. ولا يجوز نسخها أو إرسالها أو نشرها أو استخدامها خارج نطاق العمل دون موافقة مكتوبة. وتكون المخرجات التي ينشئها الموظف لحساب الشركة ملكًا لها بالقدر الذي يسمح به القانون.</p>\n\n    <div class="bar">ثامنًا: الجزاءات وإنهاء العقد وتسوية النزاعات</div>\n    <p>يخضع الموظف للائحة الجزاءات والإجراءات التأديبية المعتمدة بالشركة، مع مراعاة القانون وحقه في التحقيق والرد والتظلم. وينتهي العقد بالتراضي أو بانتهاء مدته أو لأي سبب آخر وفق القانون وشروط العقد، ويلتزم الطرف الراغب في الإنهاء بمدة الإخطار النظامية أو التعاقدية. ويسعى الطرفان إلى تسوية النزاعات وديًا، فإن تعذر ذلك تختص محاكم مطروح، مع مراعاة الاختصاص النوعي والقيمي والقواعد الآمرة التي يقررها القانون.</p>\n\n    <div class="bar">تاسعًا: الأداء والتقييم والتطوير</div>\n    <ol>\n      <li>يلتزم الموظف بتحقيق أهداف العمل والمعايير المهنية المحددة لوظيفته، والتعاون مع المدير المباشر في وضع خطة العمل ومراجعتها.</li>\n      <li>يجوز للشركة إجراء تقييم دوري للأداء، ويشمل جودة العمل والالتزام بالمواعيد والتعاون وخدمة العملاء والنتائج المحققة.</li>\n      <li>يلتزم الموظف بحضور برامج التدريب أو التوجيه المرتبطة بطبيعة العمل.</li>\n      <li>لا يعد التقييم أو التدريب وعدًا بزيادة أو ترقية إلا بقرار مكتوب من الجهة المختصة.</li>\n    </ol>\n\n    <div class="bar">عاشرًا: السلوك المهني وتعارض المصالح</div>\n    <ol>\n      <li>يلتزم الموظف بالاحترام المتبادل وحسن التعامل مع الزملاء والعملاء والموردين، ويحظر أي إساءة أو تحرش أو تهديد أو تمييز مخالف للقانون.</li>\n      <li>يلتزم الموظف بالإفصاح عن أي مصلحة شخصية قد تؤثر في نزاهة قرارات الشراء أو التوريد أو التفاوض.</li>\n      <li>لا يجوز للموظف تمثيل الشركة أو إصدار التزامات باسمها إلا في حدود الصلاحيات الممنوحة له كتابةً.</li>\n      <li>يحظر استخدام اسم الشركة أو شعارها أو بياناتها في إعلانات أو مراسلات أو حسابات شخصية دون موافقة مكتوبة.</li>\n    </ol>\n\n    <div class="bar">الحادي عشر: العهد والأجهزة والأنظمة</div>\n    <ol>\n      <li>تثبت العهد المسلمة للموظف في سجل أو نموذج مستقل، وتشمل الأجهزة والمفاتيح والبطاقات والملفات وحسابات الدخول.</li>\n      <li>يحافظ الموظف على العهد ولا يسلمها أو يسمح باستخدامها من غير المصرح لهم، ويبلغ فورًا عن الفقد أو التلف أو اختراق الحسابات.</li>\n      <li>تظل حسابات البريد والأنظمة والملفات المستخدمة في العمل ملكًا للشركة، ويجوز للشركة إدارتها أو إيقافها وفق القانون.</li>\n      <li>عند انتهاء الخدمة، يعيد الموظف جميع العهد ويلغي أي نسخ أو وصول محفوظ لديه، ويوقع على نموذج إخلاء الطرف.</li>\n    </ol>\n\n    <div class="footer-note"><span>توقيع الموظف: ................................</span><span>صفحة 2</span><span>شركة قرطبة للتوريدات</span></div>\n\n    <div class="page-break"></div>\n\n    <div class="bar">الثاني عشر: السفر والعمل خارج المقر والعمل الإضافي</div>\n    <p>يجوز تكليف الموظف بمهام خارج مقر العمل أو بالسفر لمصلحة العمل عند الحاجة، على أن تحدد الشركة المهمة والمدة والمصاريف وآلية اعتمادها. ولا ينفذ العمل الإضافي إلا بموافقة مسبقة، ويعوض عنه وفق القانون والسياسة المعتمدة.</p>\n\n    <div class="bar">الثالث عشر: حماية البيانات والتواصل الرسمي</div>\n    <p>تجمع الشركة بيانات الموظف وتستخدمها لأغراض التوظيف والرواتب والإدارة والامتثال النظامي، وتقتصر المعالجة على ما تسمح به القوانين والسياسات. ويلتزم الموظف باستخدام قنوات الشركة الرسمية في المراسلات وحماية كلمات المرور وعدم مشاركة بيانات الدخول.</p>\n\n    <div class="bar">الرابع عشر: حماية مصالح الشركة والالتزام الوظيفي</div>\n    <ol>\n      <li>يلتزم الموظف بتنفيذ أوامر وتعليمات الإدارة الصادرة من صاحب الصلاحية متى كانت مرتبطة بالعمل ومشروعة وقابلة للتنفيذ، ويطلب التوضيح كتابةً عند وجود غموض.</li>\n      <li>يمثل الرفض غير المبرر لأوامر العمل المشروعة أو تعطيل سير العمل أو إفشاء المعلومات أو إساءة استخدام الصلاحيات مخالفة تستوجب التحقيق والجزاء المناسب وفق اللائحة والقانون.</li>\n      <li>يحظر استقطاب عملاء الشركة أو مورديها أو موظفيها لحساب شخصي أو لحساب منافس، أو استخدام قوائم الأسعار أو بيانات التوريد أو فرص العمل لمصلحة خارجية، في الحدود التي يسمح بها القانون.</li>\n      <li>تؤول للشركة، بالقدر الذي يسمح به القانون، حقوق استخدام وتسليم الملفات والتقارير وقواعد البيانات والنماذج والعروض والمراسلات التي ينشئها الموظف أثناء العمل أو باستخدام موارد الشركة.</li>\n      <li>يحق للشركة تطبيق ضوابط أمن المعلومات ومراجعة استخدام أجهزتها وحساباتها وأنظمتها في حدود القانون والسياسات المعلنة، ويجوز إيقاف الوصول عند الاشتباه في خطر أمني أو مخالفة.</li>\n      <li>لا يجوز إجراء أي خصم أو تحميل مالي على الموظف إلا في الحالات وبالإجراءات التي يسمح بها القانون، وبعد توثيق الواقعة وتمكينه من الرد.</li>\n    </ol>\n\n    <div class="bar">الخامس عشر: الشرط الجزائي والتعويض</div>\n    <p>اتفق الطرفان، في الحدود التي يسمح بها القانون، على أنه إذا أخل الموظف إخلالًا جسيمًا أو متعمدًا بأي التزام جوهري وارد في هذا العقد أو اللوائح أو الملاحق المرتبطة به، وبعد ثبوت المخالفة والتحقيق فيها وتمكين الموظف من الرد، يستحق الطرف الأول شرطًا جزائيًا اتفاقيًا قدره <strong>٥٠٠٬٠٠٠ جنيه مصري (فقط خمسمائة ألف جنيه مصري لا غير)</strong>، دون إخلال بحق الشركة في طلب وقف المخالفة ورد العهد والمستندات والتعويض عن الضرر الإضافي المثبت. ولا يطبق هذا الشرط تلقائيًا على الأخطاء البسيطة أو المخالفات غير المؤثرة أو ممارسة الموظف لحق قانوني.</p>\n\n    <div class="bar">السادس عشر: اللوائح والملحقات والمرفقات المرتبطة بالعقد</div>\n    <p>يقر الطرفان بأن الوثائق التالية مرتبطة بهذا العقد وتعد جزءًا مكملًا له بعد تسليمها للموظف أو إتاحتها له:</p>\n    <table>\n      <tr><th class="number">م</th><th>الوثيقة أو المرفق</th><th>تم التسليم</th><th>التاريخ</th></tr>\n      <tr><td class="number">1</td><td>اللائحة الداخلية للموظفين في شركة قرطبة للتوريدات.</td><td>{{delivered1}}</td><td>{{deliveredDate1}}</td></tr>\n      <tr><td class="number">2</td><td>ملحق السياسات المالية والإدارية.</td><td>{{delivered2}}</td><td>{{deliveredDate2}}</td></tr>\n      <tr><td class="number">3</td><td>ملحق لائحة الجزاءات والإجراءات التأديبية.</td><td>{{delivered3}}</td><td>{{deliveredDate3}}</td></tr>\n      <tr><td class="number">4</td><td>الوصف الوظيفي المعتمد للموظف.</td><td>{{delivered4}}</td><td>{{deliveredDate4}}</td></tr>\n      <tr><td class="number">5</td><td>عرض العمل أو خطاب التعيين، إن وجد.</td><td>{{delivered5}}</td><td>{{deliveredDate5}}</td></tr>\n    </table>\n\n    <div class="subbar">ترتيب الأولوية عند التعارض</div>\n    <p>تكون الأولوية بالترتيب الآتي: القانون الواجب التطبيق، ثم عقد العمل، ثم أي شرط أكثر فائدة للموظف، ثم اللائحة الداخلية، ثم الملاحق والمرفقات والتعليمات التنفيذية. ولا يجوز تعديل أي ملحق أو مرفق مؤثر في حقوق أو التزامات الطرفين إلا كتابةً وباعتماد الجهة المختصة وإخطار الموظف.</p>\n\n    <div class="bar">السابع عشر: أحكام عامة وإقرار الموظف</div>\n    <ol>\n      <li>يمثل هذا العقد كامل الاتفاق بين الطرفين في موضوعه، ويجوز تعديله كتابةً وبموافقة الطرفين.</li>\n      <li>إذا بطل أي بند أو تعذر تطبيقه، فلا يؤثر ذلك في باقي البنود.</li>\n      <li>حرر العقد من نسختين أصليتين، تسلم كل طرف نسخة للعمل بموجبها.</li>\n      <li>يقر الموظف بأنه قرأ هذا العقد وفهم مضمونه واطلع على اللوائح والملحقات والمرفقات المشار إليها، ويلتزم بها في حدود القانون.</li>\n    </ol>\n\n    <div class="ack">\n      <strong>إقرار بالاطلاع:</strong> <span style="display:inline-block;min-width:260px;border-bottom:1px dotted #555"></span> بأنني تسلمت أو أتيح لي الاطلاع على عقد العمل واللائحة الداخلية والملحقات والمرفقات المذكورة أعلاه.\n    </div>\n\n    <div class="bar">صفحة التوقيع والاعتماد</div>\n    <div class="two-col">\n      <div class="signature"><h3>الطرف الأول — شركة قرطبة للتوريدات</h3><p>الاسم: <input /></p><p>التوقيع: <input /></p><p>التاريخ: <input /></p></div>\n      <div class="signature"><h3>الطرف الثاني — الموظف</h3><p>الاسم: <span style="display:inline-block;min-width:150px;border-bottom:1px dotted #555"></span></p><p>التوقيع: <input /></p><p>التاريخ: <input /></p></div>\n    </div>\n\n    <div class="subbar">الشهود عند الحاجة</div>\n    <table>\n      <tr><td>الشاهد الأول — الاسم: <input /></td><td>التوقيع: <input /></td></tr>\n      <tr><td>الشاهد الثاني — الاسم: <input /></td><td>التوقيع: <input /></td></tr>\n    </table>\n\n    <div class="two-col">\n      <div><div class="subbar">ختم الشركة واعتمادها</div><div class="stamp">الختم الرسمي</div></div>\n      <div><div class="subbar">ملاحظات أو تحفظات</div>{{notes}}</div>\n    </div>\n\n    <div class="footer-note"><span>توقيع الموظف: ................................</span><span>صفحة 3</span><span>شركة قرطبة للتوريدات</span></div>\n  </main>\n</body>\n</html>\n',
  internalRules:
    '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>اللائحة الداخلية للموظفين | شركة قرطبة للتوريدات</title><style>\n:root{--ink:#263238;--muted:#5b6573;--gold:#b08d3c;--line:#cbd2d9;--soft:#eef1f4;--cream:#f7f3e8;--paper:#fff}\n*{box-sizing:border-box}html{background:#e9edf1}body{margin:0;color:var(--ink);background:#e9edf1;font-family:Tahoma,Arial,sans-serif;line-height:1.75}.document{width:210mm;min-height:297mm;margin:20px auto;padding:18mm 17mm;background:var(--paper);border:1px solid #718096;box-shadow:0 5px 24px rgba(0,0,0,.12)}.page-header{display:grid;grid-template-columns:1fr 5fr 1fr;align-items:center;gap:12px;padding-bottom:7px;border-bottom:2px solid var(--gold);color:var(--muted);font-size:12px}.page-header img{width:42px;justify-self:start}.company-name{text-align:center;color:var(--ink);font-weight:700;font-size:15px}.cover{text-align:center;padding:24px 0 14px}.cover img{width:82px}.cover h1{margin:7px 0 0;font-size:28px;color:var(--ink)}.cover h2{margin:0;color:#8a6a2f;font-size:17px}.gold-rule{width:110px;margin:12px auto;border-top:2px solid var(--gold)}.notice,.ack{padding:12px 14px;margin:12px 0;border:1px solid var(--gold);border-radius:4px;background:var(--cream)}.bar{margin:17px 0 8px;padding:6px 10px;border:1px solid var(--gold);border-right:4px solid var(--ink);border-radius:3px;background:var(--soft);font-size:16px;font-weight:700}.subbar{margin:12px 0 5px;padding-bottom:3px;border-bottom:1px solid #d6c59b;color:#8a6a2f;font-weight:700}table{width:100%;border-collapse:collapse;margin:6px 0 12px}th,td{border:1px solid var(--line);padding:7px 8px;vertical-align:middle}th{background:var(--soft);font-weight:700}.label{width:25%;background:#fafafa;font-weight:700;white-space:nowrap}input,textarea{width:100%;border:0;border-bottom:1px dotted #555;padding:3px 2px;background:transparent;color:var(--ink);font:inherit;outline:none}textarea{min-height:44px;resize:vertical;border:1px dotted #777}input:focus,textarea:focus{background:#fffbea}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px}.signature{padding:12px;border:1px solid var(--gold);border-radius:4px;background:#fafaf8}.signature h3{margin:0 0 12px;text-align:center;font-size:15px}.signature p{margin:8px 0}.page-break{break-before:page;page-break-before:always}.footer-note{margin-top:18px;padding-top:7px;border-top:1px solid var(--gold);color:var(--muted);font-size:11px;display:flex;justify-content:space-between}li{margin:3px 0}.policy-list{margin-top:5px;padding-right:25px}.small{font-size:12px;color:var(--muted)}@media(max-width:850px){.document{width:100%;margin:0;padding:18px;border:0;box-shadow:none}.two-col{grid-template-columns:1fr}}@media print{html,body{background:#fff}.document{width:auto;min-height:auto;margin:0;padding:14mm 15mm;border:0;box-shadow:none}@page{size:A4;margin:0}}\n</style></head><body>\n<main class="document"><header class="page-header"><span>لائحة داخلية</span><span class="company-name">شركة قرطبة للتوريدات</span><img src="{{logo}}" alt="شعار قرطبة"></header>\n<section class="cover"><img src="{{logo}}" alt="شعار قرطبة"><h1>اللائحة الداخلية للموظفين</h1><h2>شركة قرطبة للتوريدات</h2><div class="gold-rule"></div></section>\n<div class="notice">يجب مراجعتها واعتمادها وفق قانون العمل في دولة ومقر العمل قبل التعميم.</div>\n<div class="bar">البيانات القانونية للمنشأة</div><table><tr><td class="label">الاسم التجاري</td><td>شركة قرطبة للتوريدات</td></tr><tr><td class="label">الشكل القانوني</td><td>منشأة فردية / تاجر فرد</td></tr><tr><td class="label">المالك والممثل القانوني</td><td>إيمان كامل أبو زيد عطية</td></tr><tr><td class="label">السجل التجاري</td><td>٢١٦١٨ — مكتب سجل تجاري مرسى مطروح</td></tr><tr><td class="label">الرقم القومي للمنشأة</td><td>٤٣٢٩٧٢٥٨٧</td></tr><tr><td class="label">الرقم الضريبي</td><td>٤٣٢-٩٧٢-٥٨٧ — مأمورية ضرائب مطروح</td></tr><tr><td class="label">العنوان</td><td>محافظة مطروح — شارع علم الروم</td></tr><tr><td class="label">النشاط</td><td>مواد البناء والمواد الإنشائية ومعدات السباكة والتدفئة، وتوريدات الأجهزة الكهربائية ومستلزماتها</td></tr></table>\n<div class="bar">بيانات الإصدار والاعتماد</div><table><tr><td class="label">رقم الإصدار</td><td>{{issueNo}}</td><td class="label">تاريخ الإصدار</td><td>{{issueDate}}</td></tr><tr><td class="label">تاريخ النفاذ</td><td>{{effectiveDate}}</td><td class="label">الجهة المعتمدة</td><td>{{approvingBody}}</td></tr></table>\n<div class="bar">1. الغرض والنطاق</div><p>تهدف هذه اللائحة إلى تنظيم علاقة العمل وتوضيح واجبات الموظفين وحقوقهم وحماية مصالح الشركة والعملاء والموردين. وتسري على جميع الموظفين والمتدربين والمتعاقدين بالقدر الذي تسمح به عقودهم. وفي حال التعارض مع القانون أو عقد العمل، يطبق النص الإلزامي الواجب التطبيق.</p><div class="bar">2. مبادئ السلوك المهني</div><p>يلتزم الموظف بالأمانة والنزاهة والدقة وحسن التعامل واحترام الكرامة الإنسانية، ويحظر التمييز والتنمر والتحرش والتهديد والإساءة. كما يحظر استغلال المنصب أو موارد الشركة لمنفعة شخصية أو إصدار تصريحات باسم الشركة دون تفويض.</p><div class="bar">3. الحضور والإجازات</div><p>تحدد أيام وساعات العمل وآلية الحضور والانصراف في قرار إداري مستقل. يلتزم الموظف بالحضور في الموعد وإخطار المدير قبل بداية الدوام عند التأخر أو الغياب الطارئ. تمنح الإجازات وفق القانون والعقد وبعد اعتمادها من القناة المعتمدة. لا يجوز تسجيل حضور موظف آخر أو طلب التسجيل بالنيابة عنه.</p><div class="bar">4. المسؤوليات حسب أدوار النظام</div><p>مدير النظام: يدير حسابات الموظفين والصلاحيات والإعدادات ويحمي سجلات التدقيق ولا يستخدم الصلاحية الإدارية لمنفعة شخصية.</p><p>المدير: يراجع الأعمال ويعتمد ما يقع ضمن التفويض ويتابع طلبات الأسعار ويرفع التوصيات التجارية ويصعد تعارض المصالح أو فروق الأسعار غير المبررة.</p><p>المشتريات: ينشئ طلبات الأسعار ويرسلها للموردين ويتابع الردود ويسجل العروض كما وردت ويحافظ على سرية أسعار الموردين.</p><p>مدخل البيانات: يدخل البيانات من المستندات الأصلية ويراجع الأرقام والوحدات والتواريخ ولا يعتمد أسعارًا أو يعدل بيانات جوهرية خارج الصلاحية.</p><div class="bar">5. دورة طلبات الأسعار والمشتريات</div><p>يجب تسجيل رقم الطلب والعميل والتاريخ والبنود والكميات والمواصفات والموعد المطلوب. تسجل عروض الموردين بالعملة والضرائب والشحن ومدة التوريد وشروط الدفع ومدة الصلاحية. يحظر تعديل عرض المورد أو إخفاء جزء منه، ولا يصدر التزام باسم الشركة أو أمر شراء إلا من صاحب الصلاحية. يجب توثيق كل تغيير أو اعتماد.</p><div class="bar">6. السرية وحماية البيانات</div><p>يستخدم الموظف حسابه الشخصي ويحظر مشاركة كلمة المرور أو ترك الجلسة مفتوحة. يحظر نسخ بيانات العملاء والموردين أو إرسالها إلى حساب شخصي أو جهة غير معتمدة. يجب الإبلاغ فورًا عن فقدان جهاز أو كشف كلمة مرور أو إرسال خاطئ أو دخول غير مصرح. تستمر السرية بعد انتهاء العمل بالقدر المسموح قانونًا.</p><div class="bar">7. تعارض المصالح والهدايا</div><p>يفصح الموظف عن أي علاقة شخصية أو مالية مع عميل أو مورد أو منافس، ولا يطلب أو يقبل عمولة أو هدية أو ضيافة تؤثر في القرار. لا يوجه الأعمال إلى شركة يملكها أو يملكها قريب له دون إفصاح واعتماد مكتوب.</p><div class="bar">8. أصول الشركة والتقنية</div><p>تستخدم أجهزة وحسابات الشركة لأغراض العمل المشروعة. يحظر تثبيت برامج غير معتمدة أو تعطيل وسائل الحماية أو نقل الملفات إلى أجهزة غير آمنة. يعيد الموظف الأجهزة والملفات والعهد عند الطلب أو انتهاء العلاقة.</p><div class="bar">9. الشكاوى والمخالفات</div><p>يجوز تقديم الشكوى أو البلاغ بحسن نية إلى المدير أو الموارد البشرية أو الجهة المحددة من الإدارة. تحظر معاقبة مقدم البلاغ حسن النية. تفحص الشكاوى بسرية ويمنح الأطراف فرصة عادلة للرد.</p><div class="bar">10. الإجراءات التأديبية وانتهاء العمل</div><p>تطبق الجزاءات بعد التحقق وسماع رد الموظف وبما لا يخالف القانون، مع مراعاة جسامة المخالفة وتكرارها والضرر. عند انتهاء العمل، يسلم الموظف العهد والملفات ووسائل الوصول ولا يحتفظ بنسخ غير مصرح بها.</p><div class="bar">11. بيانات الاعتماد</div><p>الاسم القانوني الكامل: {{legalName}} — الدولة والقانون: {{lawCountry}} — ساعات العمل: {{companyWorkHours}} — جهة الشكاوى: {{complaintsBody}} — مسؤول أمن المعلومات: {{infoSecOfficer}}</p>\n<div class="bar">إقرار الموظف</div><div class="ack"><span style="display:inline-block;min-width:260px;border-bottom:1px dotted #555"></span> بأنني تسلمت هذه الوثيقة واطلعت عليها وفهمت ما ورد بها، وأتعهد بالالتزام بها وبعقد العمل والقوانين والتعليمات المعتمدة.</div>\n<div class="two-col"><div class="signature"><h3>توقيع الموظف</h3><p>الاسم: <input></p><p>التوقيع: <input></p><p>التاريخ: <input></p></div><div class="signature"><h3>اعتماد الشركة</h3><p>ممثل الشركة: <input value="إيمان كامل أبو زيد عطية"></p><p>الصفة: <input value="مالك المنشأة والممثل القانوني"></p><p>التوقيع والختم: <input></p></div></div>\n<div class="footer-note"><span>توقيع الموظف: ................................</span><span>شركة قرطبة للتوريدات</span><span>صفحة قابلة للطباعة</span></div></main></body></html>',
  annex1:
    '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ملحق رقم (1) | شركة قرطبة للتوريدات</title><style>\n:root{--ink:#263238;--muted:#5b6573;--gold:#b08d3c;--line:#cbd2d9;--soft:#eef1f4;--cream:#f7f3e8;--paper:#fff}\n*{box-sizing:border-box}html{background:#e9edf1}body{margin:0;color:var(--ink);background:#e9edf1;font-family:Tahoma,Arial,sans-serif;line-height:1.75}.document{width:210mm;min-height:297mm;margin:20px auto;padding:18mm 17mm;background:var(--paper);border:1px solid #718096;box-shadow:0 5px 24px rgba(0,0,0,.12)}.page-header{display:grid;grid-template-columns:1fr 5fr 1fr;align-items:center;gap:12px;padding-bottom:7px;border-bottom:2px solid var(--gold);color:var(--muted);font-size:12px}.page-header img{width:42px;justify-self:start}.company-name{text-align:center;color:var(--ink);font-weight:700;font-size:15px}.cover{text-align:center;padding:24px 0 14px}.cover img{width:82px}.cover h1{margin:7px 0 0;font-size:28px;color:var(--ink)}.cover h2{margin:0;color:#8a6a2f;font-size:17px}.gold-rule{width:110px;margin:12px auto;border-top:2px solid var(--gold)}.notice,.ack{padding:12px 14px;margin:12px 0;border:1px solid var(--gold);border-radius:4px;background:var(--cream)}.bar{margin:17px 0 8px;padding:6px 10px;border:1px solid var(--gold);border-right:4px solid var(--ink);border-radius:3px;background:var(--soft);font-size:16px;font-weight:700}.subbar{margin:12px 0 5px;padding-bottom:3px;border-bottom:1px solid #d6c59b;color:#8a6a2f;font-weight:700}table{width:100%;border-collapse:collapse;margin:6px 0 12px}th,td{border:1px solid var(--line);padding:7px 8px;vertical-align:middle}th{background:var(--soft);font-weight:700}.label{width:25%;background:#fafafa;font-weight:700;white-space:nowrap}input,textarea{width:100%;border:0;border-bottom:1px dotted #555;padding:3px 2px;background:transparent;color:var(--ink);font:inherit;outline:none}textarea{min-height:44px;resize:vertical;border:1px dotted #777}input:focus,textarea:focus{background:#fffbea}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px}.signature{padding:12px;border:1px solid var(--gold);border-radius:4px;background:#fafaf8}.signature h3{margin:0 0 12px;text-align:center;font-size:15px}.signature p{margin:8px 0}.page-break{break-before:page;page-break-before:always}.footer-note{margin-top:18px;padding-top:7px;border-top:1px solid var(--gold);color:var(--muted);font-size:11px;display:flex;justify-content:space-between}li{margin:3px 0}.policy-list{margin-top:5px;padding-right:25px}.small{font-size:12px;color:var(--muted)}@media(max-width:850px){.document{width:100%;margin:0;padding:18px;border:0;box-shadow:none}.two-col{grid-template-columns:1fr}}@media print{html,body{background:#fff}.document{width:auto;min-height:auto;margin:0;padding:14mm 15mm;border:0;box-shadow:none}@page{size:A4;margin:0}}\n</style></head><body>\n<main class="document"><header class="page-header"><span>ملحق مالي وإداري</span><span class="company-name">شركة قرطبة للتوريدات</span><img src="{{logo}}" alt="شعار قرطبة"></header>\n<section class="cover"><img src="{{logo}}" alt="شعار قرطبة"><h1>ملحق رقم (1)</h1><h2>السياسات المالية والإدارية المكملة</h2><div class="gold-rule"></div></section>\n<div class="notice">يعد هذا الملحق جزءًا من اللائحة الداخلية، ويطبق بحسب وظيفة الموظف وصلاحياته وبما لا يخالف قانون العمل أو عقد العمل.</div>\n<div class="bar">البيانات القانونية للمنشأة</div><table><tr><td class="label">الاسم التجاري</td><td>شركة قرطبة للتوريدات</td></tr><tr><td class="label">الشكل القانوني</td><td>منشأة فردية / تاجر فرد</td></tr><tr><td class="label">المالك والممثل القانوني</td><td>إيمان كامل أبو زيد عطية</td></tr><tr><td class="label">السجل التجاري</td><td>٢١٦١٨ — مكتب سجل تجاري مرسى مطروح</td></tr><tr><td class="label">الرقم القومي للمنشأة</td><td>٤٣٢٩٧٢٥٨٧</td></tr><tr><td class="label">الرقم الضريبي</td><td>٤٣٢-٩٧٢-٥٨٧ — مأمورية ضرائب مطروح</td></tr><tr><td class="label">العنوان</td><td>محافظة مطروح — شارع علم الروم</td></tr><tr><td class="label">النشاط</td><td>مواد البناء والمواد الإنشائية ومعدات السباكة والتدفئة، وتوريدات الأجهزة الكهربائية ومستلزماتها</td></tr></table>\n<div class="bar">بيانات الإصدار والاعتماد</div><table><tr><td class="label">رقم الإصدار</td><td>{{issueNo}}</td><td class="label">تاريخ الإصدار</td><td>{{issueDate}}</td></tr><tr><td class="label">تاريخ النفاذ</td><td>{{effectiveDate}}</td><td class="label">الجهة المعتمدة</td><td>{{approvingBody}}</td></tr></table>\n<div class="bar">أولًا: السياسات المالية — 1. الصلاحيات والاعتمادات</div><p>لا ينشئ الموظف التزامًا ماليًا أو يعتمد شراءً أو خصمًا أو دفعًا إلا في حدود صلاحية مكتوبة. يحظر تجزئة الشراء لتجاوز حد الاعتماد. يجب توثيق الموافقة قبل التنفيذ، وتراجع مصفوفة الصلاحيات سنويًا أو عند تغير الهيكل.</p><div class="bar">2. الفصل بين المهام</div><p>يفصل قدر الإمكان بين طلب الشراء، واختيار المورد، واعتماد الأمر، والاستلام، ومراجعة الفاتورة، وتنفيذ الدفع، والتسجيل المحاسبي والمطابقة.</p><div class="bar">3. المشتريات والموردون</div><p>يحدد طلب الشراء الصنف والكمية والمواصفات والموعد. تطلب عروض الأسعار وفق الحدود المعتمدة، وتستثنى حالات الطوارئ أو المورد الحصري بعد توثيق السبب. تقارن العروض بالسعر والجودة والتوافر والتوريد وشروط الدفع والضمان والشحن والضرائب. يحظر إنشاء مورد وهمي أو تسجيل بيانات غير صحيحة أو مشاركة عرض مورد مع آخر بغرض غير مشروع.</p><div class="bar">4. أوامر الشراء والاستلام</div><p>لا يصدر أمر شراء إلا بناءً على طلب معتمد، ويتضمن المورد والبنود والكميات والأسعار والعملة والضرائب وشروط الدفع. لا يتم الدفع إلا بعد مطابقة أمر الشراء مع الاستلام والفاتورة. تسجل حالات العجز أو التلف أو اختلاف المواصفات فورًا.</p><div class="bar">5. المصروفات والعهد</div><p>يكون المصروف متعلقًا بالعمل ومصرحًا به، وتقدم التسوية خلال {{settleDays}} مع الفاتورة وبيان الغرض. لا تمنح عهدة جديدة قبل تسوية السابقة إلا بموافقة. يتحمل الموظف مسؤولية العهدة ويلتزم بإعادتها أو تسويتها.</p><div class="bar">6. الخزينة</div><p>يحدد مبلغ العهدة ومسؤول الخزينة بقرار إداري. لا يصرف من الخزينة إلا بسند معتمد، وتسجل الحركات فورًا، ويجرى جرد دوري ومفاجئ. يبلغ عن أي عجز أو زيادة ولا تخلط أموال الشركة بالأموال الشخصية.</p><div class="bar">7. البيع الآجل والتحصيل</div><p>لا يباع آجلًا إلا لعميل معتمد وبحد ائتماني ومدة سداد محددين. تتابع المديونيات وتوقف التسهيلات عند التأخر وفق قرار الإدارة. لا يشطب دين أو يعتمد خصم إلا بصلاحية، ولا تستلم أموال الشركة في حساب شخصي.</p><div class="bar">8. المستندات</div><p>تحفظ الفواتير وأوامر الشراء والعروض ومستندات الاستلام والمراسلات بصورة منظمة ومربوطة برقم الطلب أو الأمر. يحظر حذف أو تعديل مستند مالي دون صلاحية وأثر واضح، وتحفظ السجلات وفق القانون أو مدة الشركة المعتمدة.</p><div class="bar">9. مكافحة الاحتيال والرشوة</div><p>يحظر طلب أو قبول عمولة، أو إصدار فاتورة وهمية، أو إنشاء مورد غير حقيقي، أو تغيير الأسعار والكميات لمنفعة شخصية، أو تقسيم العملية لتجاوز الاعتماد، أو الانتقام من مبلغ حسن النية. جهة الإبلاغ: {{reportBody}} — البريد: {{reportEmail}}</p><div class="bar">ثانيًا: السياسات الإدارية — 10. الهيكل والتفويض</div><p>يكون لكل موظف مدير مباشر ووصف وظيفي وبديل عند الغياب. يكون التفويض مكتوبًا ومحدد المدة والنطاق ولا ينتقل تلقائيًا إلى موظف آخر.</p><div class="bar">11. الأداء والتدريب</div><p>تقيم الشركة الأداء على الدقة والسرعة والالتزام وجودة التواصل، وتبلغ الموظف بالنتيجة وتمنحه فرصة للتحسين. يتلقى الموظف تدريبًا على النظام والسرية والمشتريات وأمن المعلومات.</p><div class="bar">12. النظام وأمن المعلومات</div><p>الحساب شخصي، والموظف مسؤول عن العمليات المسجلة به. يحظر استخدام حساب آخر أو إدخال بيانات وهمية أو إرسال الملفات الحساسة إلى بريد شخصي. يبلغ فورًا عن فقدان جهاز أو رسالة مشبوهة أو دخول غير مصرح.</p><div class="bar">13. التواصل والعمل عن بعد</div><p>تستخدم القنوات الرسمية للقرارات والطلبات. يمكن استخدام الهاتف أو واتساب في العاجل مع توثيق القرار لاحقًا. عند العمل عن بعد يلتزم الموظف بساعات التواجد ويستخدم شبكة وجهازًا آمنين.</p><div class="bar">14. الشكاوى والجزاءات</div><p>تستقبل الشكاوى بسرية، ويمنع الانتقام من مقدم البلاغ. تحدد الجزاءات بعد التحقيق وبما يناسب المخالفة، ويمكن أن تشمل التنبيه والإنذار وخطة التصحيح وتقييد الصلاحية أو الجزاء الذي يسمح به القانون.</p><div class="bar">15. الاستمرارية والطوارئ</div><p>عند توقف النظام تسجل العمليات مؤقتًا في نموذج معتمد مع التاريخ والوقت والمنفذ ثم تدخل لاحقًا. تحدد الإدارة البديل عند غياب الموظف المسؤول، ويبلغ عن فقد البيانات أو التعطل المؤثر فورًا.</p><div class="bar">بيانات يجب استكمالها</div><p>الدولة والقانون: {{lawCountry}} — حدود المشتريات: {{purchaseLimit}} — مسؤول الحسابات: {{accountantName}} — الموارد البشرية: {{hrName}} — مدة تسوية العهد: {{advanceSettleDays}} — مدة حفظ المستندات: {{docRetentionDays}}</p>\n<div class="bar">إقرار الموظف</div><div class="ack"><span style="display:inline-block;min-width:260px;border-bottom:1px dotted #555"></span> بأنني تسلمت هذه الوثيقة واطلعت عليها وفهمت ما ورد بها، وأتعهد بالالتزام بها وبعقد العمل والقوانين والتعليمات المعتمدة.</div>\n<div class="two-col"><div class="signature"><h3>توقيع الموظف</h3><p>الاسم: <input></p><p>التوقيع: <input></p><p>التاريخ: <input></p></div><div class="signature"><h3>اعتماد الشركة</h3><p>ممثل الشركة: <input value="إيمان كامل أبو زيد عطية"></p><p>الصفة: <input value="مالك المنشأة والممثل القانوني"></p><p>التوقيع والختم: <input></p></div></div>\n<div class="footer-note"><span>توقيع الموظف: ................................</span><span>شركة قرطبة للتوريدات</span><span>صفحة قابلة للطباعة</span></div></main></body></html>',
  annex2:
    '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ملحق رقم (2) | شركة قرطبة للتوريدات</title><style>\n:root{--ink:#263238;--muted:#5b6573;--gold:#b08d3c;--line:#cbd2d9;--soft:#eef1f4;--cream:#f7f3e8;--paper:#fff}\n*{box-sizing:border-box}html{background:#e9edf1}body{margin:0;color:var(--ink);background:#e9edf1;font-family:Tahoma,Arial,sans-serif;line-height:1.75}.document{width:210mm;min-height:297mm;margin:20px auto;padding:18mm 17mm;background:var(--paper);border:1px solid #718096;box-shadow:0 5px 24px rgba(0,0,0,.12)}.page-header{display:grid;grid-template-columns:1fr 5fr 1fr;align-items:center;gap:12px;padding-bottom:7px;border-bottom:2px solid var(--gold);color:var(--muted);font-size:12px}.page-header img{width:42px;justify-self:start}.company-name{text-align:center;color:var(--ink);font-weight:700;font-size:15px}.cover{text-align:center;padding:24px 0 14px}.cover img{width:82px}.cover h1{margin:7px 0 0;font-size:28px;color:var(--ink)}.cover h2{margin:0;color:#8a6a2f;font-size:17px}.gold-rule{width:110px;margin:12px auto;border-top:2px solid var(--gold)}.notice,.ack{padding:12px 14px;margin:12px 0;border:1px solid var(--gold);border-radius:4px;background:var(--cream)}.bar{margin:17px 0 8px;padding:6px 10px;border:1px solid var(--gold);border-right:4px solid var(--ink);border-radius:3px;background:var(--soft);font-size:16px;font-weight:700}.subbar{margin:12px 0 5px;padding-bottom:3px;border-bottom:1px solid #d6c59b;color:#8a6a2f;font-weight:700}table{width:100%;border-collapse:collapse;margin:6px 0 12px}th,td{border:1px solid var(--line);padding:7px 8px;vertical-align:middle}th{background:var(--soft);font-weight:700}.label{width:25%;background:#fafafa;font-weight:700;white-space:nowrap}input,textarea{width:100%;border:0;border-bottom:1px dotted #555;padding:3px 2px;background:transparent;color:var(--ink);font:inherit;outline:none}textarea{min-height:44px;resize:vertical;border:1px dotted #777}input:focus,textarea:focus{background:#fffbea}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px}.signature{padding:12px;border:1px solid var(--gold);border-radius:4px;background:#fafaf8}.signature h3{margin:0 0 12px;text-align:center;font-size:15px}.signature p{margin:8px 0}.page-break{break-before:page;page-break-before:always}.footer-note{margin-top:18px;padding-top:7px;border-top:1px solid var(--gold);color:var(--muted);font-size:11px;display:flex;justify-content:space-between}li{margin:3px 0}.policy-list{margin-top:5px;padding-right:25px}.small{font-size:12px;color:var(--muted)}@media(max-width:850px){.document{width:100%;margin:0;padding:18px;border:0;box-shadow:none}.two-col{grid-template-columns:1fr}}@media print{html,body{background:#fff}.document{width:auto;min-height:auto;margin:0;padding:14mm 15mm;border:0;box-shadow:none}@page{size:A4;margin:0}}\n</style></head><body>\n<main class="document"><header class="page-header"><span>ملحق تأديبي</span><span class="company-name">شركة قرطبة للتوريدات</span><img src="{{logo}}" alt="شعار قرطبة"></header>\n<section class="cover"><img src="{{logo}}" alt="شعار قرطبة"><h1>ملحق رقم (2)</h1><h2>لائحة الجزاءات والإجراءات التأديبية</h2><div class="gold-rule"></div></section>\n<div class="notice">تطبق هذه اللائحة بعد مراجعتها وفق قانون العمل في دولة ومقر الشركة. لا يجوز توقيع جزاء غير مسموح به قانونًا أو عقدًا.</div>\n<div class="bar">البيانات القانونية للمنشأة</div><table><tr><td class="label">الاسم التجاري</td><td>شركة قرطبة للتوريدات</td></tr><tr><td class="label">الشكل القانوني</td><td>منشأة فردية / تاجر فرد</td></tr><tr><td class="label">المالك والممثل القانوني</td><td>إيمان كامل أبو زيد عطية</td></tr><tr><td class="label">السجل التجاري</td><td>٢١٦١٨ — مكتب سجل تجاري مرسى مطروح</td></tr><tr><td class="label">الرقم القومي للمنشأة</td><td>٤٣٢٩٧٢٥٨٧</td></tr><tr><td class="label">الرقم الضريبي</td><td>٤٣٢-٩٧٢-٥٨٧ — مأمورية ضرائب مطروح</td></tr><tr><td class="label">العنوان</td><td>محافظة مطروح — شارع علم الروم</td></tr><tr><td class="label">النشاط</td><td>مواد البناء والمواد الإنشائية ومعدات السباكة والتدفئة، وتوريدات الأجهزة الكهربائية ومستلزماتها</td></tr></table>\n<div class="bar">بيانات الإصدار والاعتماد</div><table><tr><td class="label">رقم الإصدار</td><td>{{issueNo}}</td><td class="label">تاريخ الإصدار</td><td>{{issueDate}}</td></tr><tr><td class="label">تاريخ النفاذ</td><td>{{effectiveDate}}</td><td class="label">الجهة المعتمدة</td><td>{{approvingBody}}</td></tr></table>\n<div class="bar">المادة 1: الهدف والنطاق</div><p>تنظم هذه اللائحة المخالفات الوظيفية والجزاءات والإجراءات التأديبية، وتسري على جميع موظفي شركة قرطبة للتوريدات بحسب الوظيفة والصلاحية، دون إخلال بأي حق قانوني أو تعاقدي.</p><div class="bar">المادة 2: مبادئ التأديب</div><p>لا يوقع الجزاء بناءً على إشاعة. يجب التحقق وسماع الموظف وتناسب الجزاء مع المخالفة والحياد والتوثيق والسرية وعدم الانتقام من مقدم بلاغ حسن النية.</p><div class="bar">المادة 3: المخالفات البسيطة</div><p>تشمل التأخر غير المتكرر، عدم الالتزام بإجراء الحضور، التأخر في تحديث طلب دون أثر جوهري، الإهمال البسيط في الملفات، عدم الإخطار بالتأخر، أو عدم الرد على مراسلة عمل دون مبرر.</p><div class="bar">المادة 4: المخالفات المتوسطة</div><p>تشمل تكرار التأخر أو الغياب، إهمالًا يؤخر طلبًا أو توريدًا، إدخال بيانات غير دقيقة نتيجة إهمال، عدم توثيق عرض مهم، تجاوز الصلاحية دون ضرر جسيم، إساءة استخدام النظام، أو عدم تسوية عهدة في الموعد.</p><div class="bar">المادة 5: المخالفات الجسيمة</div><p>تشمل السرقة أو الاختلاس، الرشوة والعمولة، إنشاء مورد أو عملية وهمية، التلاعب بالعروض أو الفواتير أو أوامر الشراء، حذف سجل لإخفاء مخالفة، مشاركة كلمة المرور عمدًا، تسريب الأسعار والبيانات السرية، التزوير، العمل لمصلحة منافس، الاعتداء أو التحرش، إتلاف بيانات عمدًا، أو الانتقام من مبلغ.</p><div class="bar">المادة 6: أنواع الجزاءات</div><p>قد تشمل الجزاءات، في حدود القانون: التنبيه الشفهي الموثق، التنبيه الكتابي، الإنذار الكتابي، خطة تصحيح الأداء، إعادة التدريب، تقييد صلاحية مؤقت، الخصم أو الوقف إذا أجازه القانون، وإنهاء الخدمة في الحالات المبررة قانونًا. ويجوز تجاوز التدرج في المخالفة الجسيمة بعد التحقيق.</p><div class="bar">المادة 7: عوامل تقدير الجزاء</div><p>تراعى جسامة المخالفة والضرر والقصد أو الإهمال والاستفادة الشخصية والتكرار وسجل الموظف وتعاونه وتصحيح الخطأ وأثره على العملاء والموردين ومسؤولية الموظف.</p><div class="bar">المادة 8: اكتشاف المخالفة والتحقيق الأولي</div><p>يسجل المسؤول تاريخ الواقعة ووصفها ويحفظ الأدلة ويحدد الأشخاص والأنظمة ذات الصلة ويتخذ إجراءً مؤقتًا عند الضرورة ويخطر الإدارة. التحقيق الأولي لا يعد إدانة.</p><div class="bar">المادة 9: الإخطار وجلسة التحقيق</div><p>يخطر الموظف بالمخالفة وتاريخها والقواعد محل البحث وموعد التحقيق وحقه في تقديم الرد والمستندات. تسجل الجلسة ويثبت رفض التوقيع إن وقع، ولا يجبر الموظف على الاعتراف.</p><div class="bar">المادة 10: المخالفات المالية والتقنية</div><p>يجوز مراجعة سجلات الدخول والتعديلات والمستندات والفواتير والعروض والبريد المملوك للشركة في الحدود القانونية، مع التحقق من احتمال اختراق الحساب ومنح الموظف فرصة للرد.</p><div class="bar">المادة 11: قرار التحقيق</div><p>يصدر القرار كتابةً متضمنًا بيانات الموظف والواقعة والأدلة والرد والنتيجة والجزاء وتاريخ تطبيقه وطريقة التظلم وتوقيع صاحب الصلاحية. إذا لم تثبت المخالفة تحفظ الأوراق ويرفع الإجراء المؤقت.</p><div class="bar">المادة 12: التظلم</div><p>يحق للموظف التظلم خلال {{appealDays}} من الإخطار إلى {{appealBody}}. يوضح التظلم أسباب الاعتراض والمستندات، ويراجعه شخص لم يشارك في القرار قدر الإمكان. لا يوقف التظلم الجزاء تلقائيًا إلا بقرار أو بنص قانوني.</p><div class="bar">المادة 13: التدابير المؤقتة</div><p>لحماية الأموال أو البيانات يجوز إيقاف صلاحية أو نقل مهمة أو طلب تسليم جهاز أو تغيير كلمة مرور. لا يعد التدبير المؤقت إدانة أو جزاءً، ويراجع عند زوال سببه. لا يوقف الموظف احتياطيًا إلا وفق القانون.</p><div class="bar">المادة 14: المسؤولية والسجلات</div><p>لا يعاقب الموظف لمجرد انتمائه لفريق وقعت فيه مخالفة؛ تحدد المسؤولية الفردية. تحفظ القرارات بسرية ولا يطلع عليها إلا المخولون، وتحدد مدة الاحتفاظ بها وفق القانون وسياسة الشركة.</p><div class="bar">بيانات الاعتماد</div><p>الدولة والقانون: {{lawCountry}} — جهة التحقيق: {{investigationBody}} — جهة التظلمات: {{appealsBody}} — مدة التظلم: {{appealPeriod}} — مدة حفظ الجزاءات: {{penaltyRetentionDays}}</p>\n<div class="bar">إقرار الموظف</div><div class="ack"><span style="display:inline-block;min-width:260px;border-bottom:1px dotted #555"></span> بأنني تسلمت هذه الوثيقة واطلعت عليها وفهمت ما ورد بها، وأتعهد بالالتزام بها وبعقد العمل والقوانين والتعليمات المعتمدة.</div>\n<div class="two-col"><div class="signature"><h3>توقيع الموظف</h3><p>الاسم: <input></p><p>التوقيع: <input></p><p>التاريخ: <input></p></div><div class="signature"><h3>اعتماد الشركة</h3><p>ممثل الشركة: <input value="إيمان كامل أبو زيد عطية"></p><p>الصفة: <input value="مالك المنشأة والممثل القانوني"></p><p>التوقيع والختم: <input></p></div></div>\n<div class="footer-note"><span>توقيع الموظف: ................................</span><span>شركة قرطبة للتوريدات</span><span>صفحة قابلة للطباعة</span></div></main></body></html>',
  receiptA:
    '<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>نموذج إيصال أمانة | شركة قرطبة للتوريدات</title>\n<style>\n:root{--navy:#17324d;--gold:#b18a43;--ink:#263544;--muted:#667585;--line:#d5dce3;--pale:#f2f5f8;--cream:#faf6ec}\n*{box-sizing:border-box}\nbody{margin:0;background:#e9edf1;color:var(--ink);font:14px/1.65 Tahoma,Arial,sans-serif}\n.sheet{width:min(210mm,100%);min-height:297mm;margin:22px auto;padding:13mm 15mm;background:#fff;box-shadow:0 5px 24px #15283a1a;border-top:7px solid var(--navy)}\n.header{display:flex;justify-content:space-between;align-items:center;padding-bottom:10px;border-bottom:2px solid var(--gold);color:var(--muted);font-size:11px}\n.brand{display:flex;align-items:center;gap:9px;color:var(--navy);font-weight:bold;font-size:15px}\n.brand img{width:50px;height:50px;object-fit:contain}\n.hero{position:relative;text-align:center;padding:12px 0 8px}.hero h1{margin:0;color:var(--navy);font-size:25px}.hero p{margin:2px 0;color:#8a6a2f;font-weight:bold;font-size:14px}\n.hero{text-align:center;padding:12px 0 8px}.hero h1{margin:0;color:var(--navy);font-size:25px}.hero p{margin:2px 0;color:#8a6a2f;font-weight:bold;font-size:14px}.ornament{width:76px;margin:8px auto 0;border-top:2px solid var(--gold)}\n.notice{padding:8px 11px;margin:9px 0 10px;border:1px solid #dfcc9f;border-right:4px solid var(--gold);border-radius:3px;background:var(--cream);font-size:11px}\n.section-title{margin:11px 0 5px;padding:5px 9px;background:var(--pale);border:1px solid var(--line);border-right:4px solid var(--navy);color:var(--navy);font-weight:bold;font-size:14px}\np{margin:5px 0}\ntable{width:100%;border-collapse:collapse;margin:5px 0 9px}td{border:1px solid var(--line);padding:5px 7px;vertical-align:middle}.label{width:27%;background:#f7f8fa;font-weight:bold;color:#394c5d}\ninput,textarea{width:100%;min-height:22px;border:0;border-bottom:1px dotted #8e9aa6;background:transparent;font:inherit;color:inherit;outline:none;padding:1px 3px}textarea{height:38px;border:1px dotted #8e9aa6}\n.inline{display:inline-block!important;width:170px!important;vertical-align:baseline}.short{width:115px!important}.mid{width:135px!important}\n.signatures{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:5px}.sign{padding:8px 10px;border:1px solid var(--line);border-top:3px solid var(--gold);background:#fcfcfb}.sign p{font-size:11px}.sign h3{text-align:center;margin:0 0 6px;color:var(--navy);font-size:13px}.sign p{margin:5px 0}\n.foot{margin-top:12px;padding-top:6px;border-top:1px solid var(--gold);display:flex;justify-content:space-between;color:var(--muted);font-size:10px}\n@media print{@page{size:A4;margin:0}body{background:#fff;font-size:11px;line-height:1.42}.sheet{width:210mm;min-height:297mm;margin:0;box-shadow:none;padding:7mm 12mm;border-top-width:5px}.hero{padding:7px 0 4px}.hero h1{font-size:21px}.brand img{width:42px;height:42px}.notice{padding:5px 8px;margin:6px 0 7px;font-size:10px}.section-title{margin:7px 0 3px;padding:3px 7px;font-size:12px}p{margin:3px 0}table{margin:3px 0 6px}td{padding:3px 6px}.signatures{gap:7px}.sign{padding:4px 7px}.sign h3{margin-bottom:2px}.sign p{margin:1px 0;font-size:9px}.signatures{gap:5px}.foot{margin-top:7px;padding-top:4px}input,textarea{color:#111;min-height:18px}textarea{height:28px}}\n@media(max-width:650px){.sheet{padding:18px}.signatures{grid-template-columns:1fr}.header{gap:8px}.inline{width:120px!important}}\n</style>\n</head>\n<body>\n<main class="sheet">\n<header class="header"><span>نموذج للتعبئة عند التسليم</span><div class="brand"><img src="{{logo}}" alt="شعار شركة قرطبة"><span>شركة قرطبة للتوريدات</span></div><span>إيصال أمانة</span></header>\n<section class="hero"><h1>نموذج إيصال أمانة</h1><p>لصالح شركة قرطبة للتوريدات</p><div class="ornament"></div></section>\n<div class="notice"><strong>تنبيه مهم:</strong> يُستكمل هذا النموذج وقت التسليم الفعلي للأمانة وقبل التوقيع. لا يجوز توقيعه على بياض أو استخدامه قبل إدخال بيانات الأطراف وتحديد محل الأمانة وتسليمها فعلًا.</div>\n<div class="section-title">أولًا: بيانات المبلغ والأمانة</div>\n<p>أقر أنا الموقع أدناه بأنني استلمت أمانة قدرها:</p>\n<table><tr><td class="label">المبلغ بالأرقام</td><td><strong>٥٠٠,٠٠٠.٠٠ جنيه مصري</strong></td></tr><tr><td class="label">المبلغ بالحروف</td><td><strong>فقط خمسمائة ألف جنيه مصري لا غير</strong></td></tr><tr><td class="label">الغرض من التسليم</td><td><strong>عهدة مالية مخصصة لشراء البضائع المطلوبة للعميل، وفقًا لتكليف قسم المشتريات.</strong></td></tr></table>\n<div class="section-title">ثانيًا: بيانات المستلم</div>\n<table><tr><td class="label">الاسم رباعي</td><td>{{fullName}}</td></tr><tr><td class="label">الرقم القومي / جواز السفر</td><td>{{nationalId}}</td></tr><tr><td class="label">العنوان الكامل</td><td>{{address}}</td></tr><tr><td class="label">رقم الهاتف</td><td>{{phone}}</td></tr><tr><td class="label">الصفة أو الوظيفة</td><td>{{jobTitle}}</td></tr></table>\n<div class="section-title">ثالثًا: الإقرار والالتزام</div>\n<p>أقر أنا/ <span style="display:inline-block;min-width:260px;border-bottom:1px dotted #555"></span> بأنني تسلمت من السيد/السيدة {{giverName}} الأمانة المبينة أعلاه، وقد تسلمتها تسلمًا فعليًا كاملًا بتاريخ {{receiptDate}} في مكان {{receiptPlace}}، وأتعهد بالمحافظة عليها وردها أو تسليمها وفق الغرض المتفق عليه.</p>\n<table><tr><td class="label">بيانات إضافية</td><td>{{notes}}</td></tr></table>\n<p>أقر بأن جميع البيانات الواردة في هذا النموذج قد تم استكمالها ومراجعتها قبل التوقيع، وأن التوقيع تم بعد استلام الأمانة فعليًا، مع الالتزام بالقوانين واللوائح المعمول بها.</p>\n<div class="section-title">رابعًا: التوقيعات</div>\n<div class="signatures"><div class="sign"><h3>المستلم / الأمين</h3><p>الاسم: <span style="display:inline-block;min-width:150px;border-bottom:1px dotted #555"></span></p><p>التوقيع: <input></p><p>التاريخ: <input></p></div><div class="sign"><h3>ممثل شركة قرطبة للتوريدات</h3><p>الاسم: <strong>إيمان كامل أبو زيد عطية</strong></p><p>الصفة والكيان: <strong>مالك المنشأة والممثل القانوني — منشأة فردية / تاجر فرد</strong></p><p>السجل التجاري: <strong>٢١٦١٨ — مكتب سجل تجاري مرسى مطروح</strong></p><p>الرقم القومي للمنشأة: <strong>٤٣٢٩٧٢٥٨٧</strong>　|　الرقم الضريبي: <strong>٤٣٢-٩٧٢-٥٨٧</strong></p><p>الرقم الموحد للسجل التجاري: <strong>٢١٦١٨، ٧٠٠٠٠، ١٠٤٢٠</strong></p><p>العنوان: <strong>محافظة مطروح — شارع علم الروم</strong></p><p>التوقيع والختم: <input></p></div></div>\n<div class="section-title">خامسًا: الشهود عند الحاجة</div>\n<table><tr><td>الشاهد الأول — الاسم: <input></td><td>التوقيع: <input></td></tr><tr><td>الشاهد الثاني — الاسم: <input></td><td>التوقيع: <input></td></tr></table>\n<footer class="foot"><span>توقيع المستلم: ................................</span><span>شركة قرطبة للتوريدات</span><span>نموذج للتعبئة عند التسليم</span></footer>\n</main>\n</body></html>\n',
  receiptB:
    '<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>نموذج إيصال أمانة | شركة قرطبة للتوريدات</title>\n<style>\n:root{--ink:#263238;--muted:#5b6573;--gold:#b08d3c;--line:#cbd2d9;--soft:#eef1f4;--cream:#f7f3e8}\n*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--ink);font-family:Tahoma,Arial,sans-serif;line-height:1.8}.document{max-width:900px;margin:0 auto;padding:34px 48px;border:1px solid #718096}.page-header{display:grid;grid-template-columns:1fr 5fr 1fr;align-items:center;padding-bottom:8px;border-bottom:2px solid var(--gold);color:var(--muted);font-size:12px}.page-header img{width:42px}.company{text-align:center;color:var(--ink);font-weight:700;font-size:16px}.cover{text-align:center;padding:22px 0 12px}.cover img{width:80px}.cover h1{margin:5px 0 0;font-size:30px}.cover h2{margin:0;color:#8a6a2f;font-size:18px}.rule{width:120px;margin:12px auto;border-top:2px solid var(--gold)}.notice{padding:12px 15px;margin:12px 0;border:1px solid var(--gold);border-radius:4px;background:var(--cream)}.bar{margin:18px 0 8px;padding:7px 11px;border:1px solid var(--gold);border-right:4px solid var(--ink);background:var(--soft);font-weight:700;font-size:17px}table{width:100%;border-collapse:collapse;margin:7px 0 14px}td{border:1px solid var(--line);padding:8px;vertical-align:middle}.label{width:25%;background:#fafafa;font-weight:700}input,textarea{width:100%;border:0;border-bottom:1px dotted #555;background:transparent;font:inherit;padding:3px;outline:none}textarea{border:1px dotted #777;min-height:70px}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.sign{padding:14px;border:1px solid var(--gold);background:#fafaf8}.sign h3{text-align:center;margin:0 0 12px;font-size:16px}.sign p{margin:8px 0}.foot{margin-top:22px;padding-top:8px;border-top:1px solid var(--gold);display:flex;justify-content:space-between;color:var(--muted);font-size:11px}@media(max-width:700px){.document{border:0;padding:18px}.two{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<main class="document">\n<header class="page-header"><span>نموذج قانوني</span><span class="company">شركة قرطبة للتوريدات</span><img src="{{logo}}" alt="شعار قرطبة"></header>\n<section class="cover"><img src="{{logo}}" alt="شعار قرطبة"><h1>نموذج إيصال أمانة</h1><h2>لصالح شركة قرطبة للتوريدات</h2><div class="rule"></div></section>\n<div class="notice"><strong>تنبيه مهم:</strong> هذا نموذج يتم استكمال جميع بياناته وقت التسليم الفعلي للأمانة وقبل التوقيع. لا يجوز توقيعه على بياض أو استخدامه قبل إدخال بيانات الأطراف وتحديد محل الأمانة وتسليمها فعلًا.</div>\n<div class="bar">أولًا: بيانات المبلغ والأمانة</div>\n<p>أقر أنا الموقع أدناه بأنني استلمت أمانة قدرها:</p>\n<table><tr><td class="label">المبلغ بالأرقام</td><td><strong>٥٠٠٬٠٠٠ جنيه مصري</strong></td></tr><tr><td class="label">المبلغ بالحروف</td><td><strong>فقط خمسمائة ألف جنيه مصري لا غير</strong></td></tr><tr><td class="label">نوع الأمانة أو وصفها</td><td>{{amountType}}</td></tr><tr><td class="label">الغرض من التسليم</td><td>{{purpose}}</td></tr></table>\n<div class="bar">ثانيًا: بيانات المستلم</div>\n<table><tr><td class="label">الاسم رباعي</td><td>{{fullName}}</td></tr><tr><td class="label">الرقم القومي / جواز السفر</td><td>{{nationalId}}</td></tr><tr><td class="label">العنوان الكامل</td><td>{{address}}</td></tr><tr><td class="label">رقم الهاتف</td><td>{{phone}}</td></tr><tr><td class="label">الصفة أو الوظيفة</td><td>{{jobTitle}}</td></tr></table>\n<div class="bar">ثالثًا: بيانات المسلم والمستفيد</div>\n<table><tr><td class="label">اسم المسلم أو المسلّم</td><td>{{giverName}}</td></tr><tr><td class="label">بياناته وعنوانه</td><td>{{giverDetails}}</td></tr><tr><td class="label">المستفيد / المسلّم إليه</td><td><strong>شركة قرطبة للتوريدات</strong></td></tr><tr><td class="label">ممثل الشركة</td><td><strong>إيمان كامل أبو زيد عطية — مالك المنشأة والممثل القانوني</strong></td></tr><tr><td class="label">عنوان الشركة</td><td>محافظة مطروح — شارع علم الروم</td></tr></table>\n<div class="bar">رابعًا: الإقرار والالتزام</div>\n<p>أقر أنا/ <span style="display:inline-block;min-width:260px;border-bottom:1px dotted #555"></span> بأنني تسلمت من السيد/السيدة {{giverName}} الأمانة المبينة أعلاه، وقد تسلمتها تسلمًا فعليًا كاملًا بتاريخ {{receiptDate}} في مكان {{receiptPlace}}، وأتعهد بالمحافظة عليها وردها أو تسليمها إلى المستفيد المحدد أعلاه.</p>\n<table><tr><td class="label">موعد الرد أو التسليم</td><td>{{returnDate}}</td></tr><tr><td class="label">مكان الرد أو التسليم</td><td>{{returnPlace}}</td></tr><tr><td class="label">طريقة الرد أو التسليم</td><td>{{returnMethod}}</td></tr><tr><td class="label">بيانات إضافية</td><td>{{notes}}</td></tr></table>\n<p>أقر بأن جميع البيانات الواردة في هذا النموذج قد تم استكمالها ومراجعتها قبل التوقيع، وأن التوقيع تم بعد استلام الأمانة فعليًا، مع الالتزام بالقوانين واللوائح المعمول بها.</p>\n<div class="bar">خامسًا: التوقيعات</div>\n<div class="two"><div class="sign"><h3>المستلم / الأمين</h3><p>الاسم: <span style="display:inline-block;min-width:150px;border-bottom:1px dotted #555"></span></p><p>التوقيع: <input></p><p>التاريخ: <input></p></div><div class="sign"><h3>ممثل شركة قرطبة للتوريدات</h3><p>الاسم: <strong>إيمان كامل أبو زيد عطية</strong></p><p>الصفة: <strong>مالك المنشأة والممثل القانوني</strong></p><p>التوقيع والختم: <input></p></div></div>\n<div class="bar">سادسًا: الشهود عند الحاجة</div><table><tr><td>الشاهد الأول — الاسم: <input></td><td>التوقيع: <input></td></tr><tr><td>الشاهد الثاني — الاسم: <input></td><td>التوقيع: <input></td></tr></table>\n<div class="foot"><span>توقيع المستلم: ................................</span><span>شركة قرطبة للتوريدات</span><span>نموذج للتعبئة عند التسليم</span></div>\n</main>\n</body></html>\n',
} as const;

